use std::env;

/// MR-2011: every IPC command `main.rs` registers (`ipc_handler`), in its
/// order. tauri-build turns each into an `allow-<command>` / `deny-<command>`
/// permission (`src-tauri/permissions/autogenerated/`, written by the build),
/// and having an app manifest at all is what makes Tauri check the app's own
/// commands against the capabilities. Without one, every registered command
/// was callable from any window or webview of the app (tauri 2.12
/// `webview/mod.rs`, `on_message`: the ACL is consulted for an app command
/// only when `has_app_acl_manifest`).
///
/// A command is callable only once `capabilities/default.json` grants its
/// `allow-<command>` to the main window, so a new command goes in four places:
/// `generate_handler!` in main.rs, this list, that capability (if the UI
/// calls it), and `FRONTEND_COMMANDS` in `src/__tests__/ipc-contracts.test.ts`.
/// That test and `src/commands/app_permission_tests.rs` fail when they differ.
const APP_COMMANDS: &[&str] = &[
    // Authentication
    "login",
    "login_anonymous",
    "register_anonymous",
    "native_oauth_login",
    "logout",
    "get_auth_state",
    "verify_2fa",
    "delete_account",
    "deletion_preflight",
    "export_user_data",
    "end_expired_session",
    // VPN operations
    "connect_vpn",
    "disconnect_vpn",
    "get_vpn_status",
    "get_vpn_stats",
    "quick_connect",
    "reapply_vpn_settings",
    "get_admin_status",
    // Server management
    "get_servers",
    "ping_server",
    // Settings
    "get_settings",
    "save_settings",
    "set_autostart",
    "reset_settings",
    "set_crash_reports_enabled",
    "record_consent",
    "delete_logs",
    // Kill switch
    "get_killswitch_status",
    "set_killswitch_live",
    // Split Tunneling
    "list_installed_apps",
    // Auto-updater
    "get_app_version",
    "check_for_updates",
    "install_update",
    "get_required_update",
    "take_update_resume",
    // Settings › About › Licences
    "get_third_party_notices",
    // Extended VPN info
    "get_subscription_status",
    "get_usage_stats",
    "get_client_config",
    // Multi-Hop (Double VPN)
    "get_multi_hop_routes",
    "connect_multi_hop",
    // Port Forwarding
    "get_port_forwards",
    "create_port_forward",
    "delete_port_forward",
    // Vouchers
    "redeem_voucher",
    // Speed Test
    "run_speed_test_command",
    // Biometric (Windows Hello)
    "check_biometric_available",
    "set_biometric_enabled",
    "authenticate_biometric",
    // Deep link captured at cold start
    "take_pending_deep_link",
    // The window up from the tray
    "show_main_window",
    // The anonymous account number, kept out of clipboard history
    "copy_sensitive",
];

fn main() {
    let attrs = tauri_build::Attributes::new()
        .app_manifest(tauri_build::AppManifest::new().commands(APP_COMMANDS));

    // Embed the Windows application manifest (requireAdministrator + OS
    // compatibility) through Tauri's own build mechanism.
    //
    // IMPORTANT: do NOT also embed a manifest via `winres` (the previous
    // approach). tauri-build already injects its own application manifest, so a
    // second winres-embedded manifest collides at link time and the
    // `requestedExecutionLevel` is silently dropped from the final exe — that
    // was the root cause of "the VPN doesn't run as administrator". Feeding our
    // manifest to tauri-build makes it the single source of truth.
    #[cfg(windows)]
    let attrs = attrs.windows_attributes(
        tauri_build::WindowsAttributes::new().app_manifest(include_str!("app.manifest")),
    );

    tauri_build::try_build(attrs).expect("failed to run tauri-build");

    // ── Crash reporting must not ship inert ─────────────────────────
    //
    // `utils/crash_report.rs` reads the DSN with `option_env!`, so an absent
    // one compiles to `""` and the Sentry client becomes a silent no-op: the
    // build is green, the artifact is signed and shipped, and the crash
    // reporter does not exist. That is how the Android client spent months
    // with a blank DSN (Mobile-Client #357), and a `cargo:warning` in a
    // twelve-minute build is not a control — it is a line of scrollback.
    //
    // A DSN in the binary does NOT mean reports are sent: crash reporting is
    // opt-in at runtime and OFF until the user turns it on (audit 2026-09-29,
    // C-3). The gate here only guarantees the opt-in can work.
    //
    // THE REBUILD TRIGGER IS LOAD-BEARING. Cargo caches a build script by
    // its declared inputs; without this line the check below would be
    // evaluated once and then never again, so setting the secret for the
    // first time would not re-run it — and CI restores `target/` through
    // Swatinem/rust-cache on every job. (The crate body needs no such
    // declaration: cargo tracks `option_env!` itself. Verified by building
    // the same crate with the variable unset, then set, then changed —
    // each build recompiled and produced the new value.)
    println!("cargo:rerun-if-env-changed=SENTRY_DSN");
    println!("cargo:rerun-if-env-changed=BIRDO_ALLOW_MISSING_SENTRY_DSN");
    let profile = env::var("PROFILE").unwrap_or_default();
    if profile == "release" {
        let dsn = env::var("SENTRY_DSN").unwrap_or_default();
        let dsn = dsn.trim();
        let opted_out = !env::var("BIRDO_ALLOW_MISSING_SENTRY_DSN")
            .unwrap_or_default()
            .is_empty();
        if dsn.is_empty() {
            if opted_out {
                println!(
                    "cargo:warning=BUILDING A RELEASE WITH NO CRASH REPORTING. This artifact \
                     cannot report a crash. Never ship it."
                );
            } else {
                panic!(
                    "SENTRY_DSN is not set — refusing to build a release artifact that \
                     cannot report crashes.\n  \
                     CI: the secret is passed at job level by the build jobs in \
                     .github/workflows/; check `gh secret list`.\n  \
                     Local: SENTRY_DSN=https://...@o....ingest.de.sentry.io/... cargo build \
                     --release\n  \
                     Deliberately without: BIRDO_ALLOW_MISSING_SENTRY_DSN=1\n  \
                     See docs/SENTRY-SETUP.md."
                );
            }
        } else if !dsn.starts_with("https://") || !dsn.contains('@') {
            panic!(
                "SENTRY_DSN does not look like a DSN (expected \
                 https://<key>@<host>/<project-id>). A project slug or an auth token \
                 (sntrys_...) would compile and then silently fail to ingest."
            );
        } else {
            println!(
                "cargo:warning=Sentry: release build has a DSN — crash reporting is ARMED \
                 (opt-in: nothing is sent until the user turns it on)."
            );
        }
    }

    // Linux: check for required system libraries
    #[cfg(target_os = "linux")]
    {
        // Ensure pkg-config can find GTK and WebKit (required by Tauri on Linux)
        println!("cargo:rerun-if-env-changed=PKG_CONFIG_PATH");
    }

    // Copy wintun.dll to output directory (Windows only)
    #[cfg(windows)]
    {
        use std::fs;
        use std::path::Path;

        let out_dir = env::var("OUT_DIR").unwrap();
        let profile = if out_dir.contains("debug") {
            "debug"
        } else {
            "release"
        };

        let target_dir = Path::new("target").join(profile);
        let wintun_src = Path::new("wintun-extract/wintun/bin/amd64/wintun.dll");
        let wintun_dst = target_dir.join("wintun.dll");

        if wintun_src.exists() && !wintun_dst.exists() {
            if let Err(e) = fs::copy(wintun_src, &wintun_dst) {
                println!("cargo:warning=Failed to copy wintun.dll: {}", e);
            } else {
                println!("cargo:warning=Copied wintun.dll to {:?}", wintun_dst);
            }
        }
    }
}
